# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step_and_labels(self):
        labels = round_spans([Span(542, 1038)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_midpoint_rounds_up(self):
        labels = round_spans([Span(555, 1005)], 30)
        self.assertEqual(labels, ["09:30-17:00 (7h 30m)"])

    def test_end_of_day_is_labelled_24_00(self):
        labels = round_spans([Span(1380, 1440)], 60)
        self.assertEqual(labels, ["23:00-24:00 (1h 0m)"])

    def test_span_that_collapses_is_rejected(self):
        with self.assertRaises(ValueError):
            round_spans([Span(542, 546)], 15)

    def test_valid_steps_are_accepted(self):
        for step in (1, 5, 15, 60):
            round_spans([], step)

    def test_bad_steps_are_rejected(self):
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                round_spans([], step)
